    root,
    activeLeafId: layout.activeLeafId ? (leafIdMap.get(layout.activeLeafId) ?? layout.activeLeafId) : null,
    expandedLeafId: layout.expandedLeafId ? (leafIdMap.get(layout.expandedLeafId) ?? layout.expandedLeafId) : null,
